<template>
  <article class="jf-ui jf-order-detail">
    <div class="jf-row jf-between"><strong>{{ order.code }} · {{ money(order.total) }}</strong><a v-if="safeLink(order.url)" :href="safeLink(order.url)" target="_blank" rel="noopener noreferrer">Mở trong CRM</a></div>
    <p class="jf-muted">Cập nhật {{ dateTime(updatedAt) }}<span v-if="stale"> · Bản lưu gần nhất</span></p>
    <dl class="jf-order-status"><div v-for="(value, label) in { 'Duyệt đơn': order.approval?.label, 'Xử lý hàng': order.processing?.label, 'Thanh toán': order.payment?.label, 'Giao hàng': order.delivery?.label }" :key="label"><dt>{{ label }}</dt><dd>{{ value || 'Chưa cập nhật' }}</dd></div></dl>
    <section class="jf-section"><h3>Sản phẩm</h3><p v-if="!order.lines.length" class="jf-muted">Chưa có thông tin sản phẩm.</p><div v-for="(line, i) in order.lines" :key="i" class="jf-detail-product"><div class="jf-row jf-between"><div><b>{{ line.name }}</b><p class="jf-muted">{{ line.variant }}{{ line.kind === 'custom' ? ' · Đặt riêng' : '' }}</p></div><span>{{ line.quantity }} {{ line.unit }} × {{ money(line.unitPrice) }}</span></div><details v-if="Object.keys(line.specifications).length || line.attachments.length || line.kind === 'custom'"><summary>Quy cách và tài liệu</summary><p v-if="line.kind === 'custom'">Giá đề xuất: {{ money(line.proposedPrice) }}</p><p v-for="(value, key) in line.specifications" :key="key"><b>{{ specLabel(String(key)) }}:</b> {{ value || 'Chưa cập nhật' }}</p><p v-for="file in line.attachments" :key="file.mediaId">{{ file.name }}</p></details></div></section>
    <section class="jf-section jf-grid"><div><h3>Người nhận</h3><template v-if="order.recipient"><p>{{ order.recipient.name }} · {{ order.recipient.phone }}</p><p>{{ order.recipient.address }}</p></template><p v-else class="jf-muted">Chưa có thông tin giao hàng.</p><p v-if="order.orderedBy">Người đặt: {{ order.orderedBy }}</p><p v-if="order.owner">Phụ trách: {{ order.owner }}</p><p v-if="order.desiredDate">Ngày khách mong muốn: {{ order.desiredDate }}</p><p v-if="order.confirmedDeliveryDate">Ngày xác nhận giao: {{ order.confirmedDeliveryDate }}</p></div><div><h3>Tiền hàng</h3><dl class="jf-totals"><template v-for="(amount, label) in amounts" :key="label"><dt>{{ label }}</dt><dd>{{ money(amount) }}</dd></template></dl></div></section>
    <details><summary>Thanh toán <span class="jf-muted">({{ order.payments?.length || 0 }})</span></summary><p v-if="!order.payments?.length" class="jf-muted">Chưa có lịch sử thanh toán.</p><div v-for="p in order.payments" :key="p.id" class="jf-history"><div class="jf-row jf-between"><b>{{ paymentLabel(p.type) }}</b><span>{{ money(p.amount) }}</span></div><p class="jf-muted">{{ dateTime(p.date) }}</p><p v-if="p.note">{{ p.note }}</p></div></details>
    <details><summary>Sản xuất và lắp đặt <span class="jf-muted">({{ order.production?.length || 0 }})</span></summary><p v-if="!order.production?.length" class="jf-muted">Chưa có tiến độ sản xuất, lắp đặt.</p><div v-for="(p, i) in order.production" :key="i" class="jf-history"><b>{{ p.label }}</b><p class="jf-muted">{{ dateTime(p.date) }}</p><p v-if="p.note">{{ p.note }}</p></div></details>
    <details><summary>Vận chuyển <span class="jf-muted">({{ order.shipments?.length || 0 }} đợt)</span></summary><p v-if="!order.shipments?.length" class="jf-muted">Chưa có thông tin vận chuyển.</p><section v-for="s in order.shipments" :key="s.id" class="jf-history"><h3>{{ s.carrier }} · {{ s.trackingCode }}</h3><p>{{ s.status }}</p><a v-if="safeLink(s.trackingUrl)" :href="safeLink(s.trackingUrl)" target="_blank" rel="noopener noreferrer">Tra cứu vận đơn</a><p v-for="(l, i) in s.lines" :key="i">{{ l.name }} · {{ l.quantity }} {{ l.unit }}</p><p v-for="(h, i) in s.history" :key="i"><span class="jf-muted">{{ dateTime(h.date) }}</span> · {{ h.label }}{{ h.note ? ' · '+h.note : '' }}</p></section></details>
    <details><summary>Trả hàng và hoàn tiền <span class="jf-muted">({{ order.returns?.length || 0 }})</span></summary><p v-if="!order.returns?.length" class="jf-muted">Chưa có hàng trả lại.</p><div v-for="r in order.returns" :key="r.id" class="jf-history"><div class="jf-row jf-between"><b>{{ r.status }}</b><span>Hoàn {{ money(r.refunded) }}</span></div><p v-for="(l, i) in r.lines" :key="i">{{ l.name }} · {{ l.quantity }} {{ l.unit }}</p></div></details>
  </article>
</template>
<script setup lang="ts">
import { computed } from 'vue';
import { dateTime, money, safeLink, type Order } from '@/api/commerce';
import './commerce.css';
const props = defineProps<{ order: Order; updatedAt: string; stale?: boolean }>();
const amounts = computed(() => ({ 'Tiền hàng': props.order.amounts?.subtotal, 'Giảm giá': props.order.amounts?.discount, 'Phí giao': props.order.amounts?.shipping, 'Thuế': props.order.amounts?.tax, 'Tổng đơn': props.order.total, 'Tiền cọc': props.order.amounts?.deposit, 'Đã thu': props.order.amounts?.collected, 'Đã hoàn': props.order.amounts?.refunded, 'Còn phải thu': props.order.amounts?.due }));
const specLabel = (key: string) => ({ measurements: 'Số đo', material: 'Chất liệu', color: 'Màu', sewing: 'Kiểu may', accessories: 'Phụ kiện', installation: 'Lắp đặt' }[key] || key.replaceAll('_', ' '));
const paymentLabel = (key: string) => ({ deposit: 'Đặt cọc', payment: 'Thu tiền', refund: 'Hoàn tiền' }[key] || key);
</script>
<style scoped>
.jf-order-status { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px; padding: 16px 0; margin: 0; border-bottom: 1px solid var(--line); }.jf-order-status dt { color: var(--ink-3); font-size: 12px; }.jf-order-status dd { margin: 4px 0 0; font-weight: 500; }
.jf-detail-product { padding: 12px 0; border-bottom: 1px solid var(--line-2); }.jf-detail-product p { margin: 3px 0; }.jf-detail-product details { border: 0; padding-bottom: 0; }.jf-history { padding: 12px 0; border-bottom: 1px solid var(--line-2); }
@media(max-width:600px) { .jf-order-status { grid-template-columns: repeat(2,minmax(0,1fr)); } }
</style>
